import Foundation
import XCTest
@testable import ColorComposerCore

/// Solver parity against the golden-vector corpus generated by the Elixir
/// `color_matching` service (viamin/color_matching#111, landed in #112).
///
/// The corpus is committed verbatim at
/// `Tests/ColorComposerCoreTests/Fixtures/parity/v1/corpus.json` and is the
/// parity contract for `WeightedSquaredErrorScorer` + `CompositionSolver`
/// selection: per-candidate scores, missing-measurement exclusion,
/// earliest-index-wins tie-breaking, and channel weighting must agree with
/// the Elixir `ColorMatching.WeightedSquaredError` / `best_match` results
/// stored in the fixture. See `docs/PARITY_CORPUS.md` for the schema and the
/// refresh procedure.
final class SolverParityCorpusTests: XCTestCase {
    private static let fixtureURL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()
        .appendingPathComponent("Fixtures/parity/v1/corpus.json")

    private enum ScoreValue: Equatable {
        case excluded
        case value(Double)
    }

    private struct CorpusVector: Decodable {
        let index: Int?
        let hexColor: String
        let channels: [String: Double]

        enum CodingKeys: String, CodingKey {
            case index
            case hexColor = "hex_color"
            case channels
        }
    }

    private struct CorpusScore: Decodable {
        let index: Int
        let score: ScoreValue

        enum CodingKeys: String, CodingKey {
            case index
            case score
        }

        init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            index = try container.decode(Int.self, forKey: .index)
            if let value = try? container.decode(Double.self, forKey: .score) {
                score = .value(value)
            } else if
                let marker = try? container.decode(String.self, forKey: .score),
                marker == "excluded"
            {
                score = .excluded
            } else {
                throw DecodingError.dataCorruptedError(
                    forKey: .score,
                    in: container,
                    debugDescription: "score must be a number or \"excluded\""
                )
            }
        }
    }

    private struct CorpusExpected: Decodable {
        let scores: [CorpusScore]
        let error: Double?
        let selectedIndex: Int?
        let selectedHexColor: String?
        let tieBroke: Bool?
        let tiedIndices: [Int]

        enum CodingKeys: String, CodingKey {
            case scores
            case error
            case selectedIndex = "selected_index"
            case selectedHexColor = "selected_hex_color"
            case tieBroke = "tie_broke"
            case tiedIndices = "tied_indices"
        }
    }

    private struct CorpusScenario: Decodable {
        let id: String
        let description: String
        let palette: [CorpusVector]
        let target: CorpusVector
        let weights: [String: Double]
        let expected: CorpusExpected
    }

    private struct ParityCorpus: Decodable {
        let algorithmVersion: Int
        let lightSources: [String]
        let missingPolicy: String
        let scorer: String
        let selection: String
        let scenarios: [CorpusScenario]

        enum CodingKeys: String, CodingKey {
            case algorithmVersion = "algorithm_version"
            case lightSources = "light_sources"
            case missingPolicy = "missing_policy"
            case scorer
            case selection
            case scenarios
        }
    }

    private func loadCorpus(file: StaticString = #filePath, line: UInt = #line) throws -> ParityCorpus {
        let url = Self.fixtureURL
        guard FileManager.default.fileExists(atPath: url.path) else {
            XCTFail("Parity corpus fixture is missing at \(url.path); see docs/PARITY_CORPUS.md", file: file, line: line)
            throw CocoaError(.fileNoSuchFile)
        }
        return try JSONDecoder().decode(ParityCorpus.self, from: Data(contentsOf: url))
    }

    private func channelWeights(_ raw: [String: Double]) -> ChannelWeights {
        func weight(_ condition: LightingCondition) -> Double {
            raw[condition.rawValue] ?? 0
        }
        return ChannelWeights(
            white: weight(.white),
            red: weight(.red),
            green: weight(.green),
            blue: weight(.blue),
            lps: weight(.lps)
        )
    }

    private func paletteColor(from vector: CorpusVector, order: Int) throws -> PaletteColor {
        let rgb = try XCTUnwrap(RGBColor(hex: vector.hexColor), "unparseable hex \(vector.hexColor)")
        var responses: [LightingCondition: IlluminationResponse] = [:]
        for (key, brightness) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                responses[condition] = IlluminationResponse(brightness: brightness)
            }
        }
        return PaletteColor(
            id: vector.index ?? order,
            hex: vector.hexColor,
            rgb: rgb,
            responses: responses
        )
    }

    private func targetVector(from vector: CorpusVector) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                brightness[condition] = value
            }
        }
        return TargetResponseVector(brightness)
    }

    /// Palette in scenario order, with the corpus's own index fields asserted
    /// contiguous so array position is the selection index (mirrors the
    /// upstream `Enum.sort_by(& &1["index"])` replay).
    private func orderedPalette(_ scenario: CorpusScenario) throws -> [PaletteColor] {
        let ordered = scenario.palette.sorted { ($0.index ?? -1) < ($1.index ?? -1) }
        XCTAssertEqual(
            ordered.map(\.index),
            Array(0..<ordered.count),
            "scenario \(scenario.id): palette index fields must be 0..<n"
        )
        return try ordered.enumerated().map { try paletteColor(from: $1, order: $0) }
    }

    private func score(
        _ scorer: WeightedSquaredErrorScorer,
        candidate: PaletteColor,
        target: TargetResponseVector,
        weights: ChannelWeights
    ) -> ScoreValue {
        switch scorer.score(candidate: candidate, target: target, weights: weights) {
        case .excluded: return .excluded
        case .score(let value): return .value(value)
        }
    }

    // MARK: - Corpus fixture invariants

    func testCorpusFixtureIsCommittedAndStamped() throws {
        let corpus = try loadCorpus()

        XCTAssertEqual(corpus.algorithmVersion, 1)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, LightingCondition.allCases.map(\.rawValue))
    }

    /// Mirrors the upstream corpus test: the corpus must keep at least one
    /// intentionally tied scenario and at least one with no selection at all,
    /// otherwise the parity contract stops covering ties and exclusions.
    func testCorpusCoversTiesAndNullSelections() throws {
        let corpus = try loadCorpus()

        XCTAssertGreaterEqual(corpus.scenarios.filter { $0.expected.tieBroke == true }.count, 1)
        XCTAssertGreaterEqual(corpus.scenarios.filter { $0.expected.selectedIndex == nil }.count, 1)
    }

    // MARK: - Scorer parity

    /// Every scenario's per-candidate scores, selection, error, and tie
    /// evidence must match `WeightedSquaredErrorScorer` exactly (exact Double
    /// equality, as the upstream ExUnit replay asserts exact float equality).
    func testScorerMatchesEveryScenarioExactly() throws {
        let corpus = try loadCorpus()
        let scorer = WeightedSquaredErrorScorer()
        XCTAssertFalse(corpus.scenarios.isEmpty)

        for scenario in corpus.scenarios {
            let palette = try orderedPalette(scenario)
            let target = targetVector(from: scenario.target)
            let weights = channelWeights(scenario.weights)
            let expectedScores = scenario.expected.scores.sorted { $0.index < $1.index }

            guard expectedScores.map(\.index) == Array(0..<palette.count) else {
                XCTFail("scenario \(scenario.id): expected score entries must cover every palette index")
                continue
            }

            var results: [ScoreValue] = []
            for candidate in palette {
                results.append(score(scorer, candidate: candidate, target: target, weights: weights))
            }

            for (index, result) in results.enumerated() {
                XCTAssertEqual(
                    result,
                    expectedScores[index].score,
                    "scenario \(scenario.id): score for candidate \(index) disagrees with the corpus"
                )
            }

            var selectedIndex: Int?
            var best: Double?
            for (index, result) in results.enumerated() {
                guard case .value(let value) = result else { continue }
                if best.map({ value < $0 }) ?? true {
                    best = value
                    selectedIndex = index
                }
            }

            if scenario.expected.selectedIndex == nil {
                XCTAssertNil(selectedIndex, "scenario \(scenario.id): expected no selection")
                XCTAssertNil(scenario.expected.error)
                XCTAssertNil(scenario.expected.tieBroke)
                XCTAssertEqual(scenario.expected.tiedIndices, [], "scenario \(scenario.id)")
            } else {
                let selected = try XCTUnwrap(selectedIndex, "scenario \(scenario.id): expected a selection")
                let winningError = try XCTUnwrap(best, "scenario \(scenario.id): expected a winning error")
                let expectedError = try XCTUnwrap(
                    scenario.expected.error,
                    "scenario \(scenario.id): corpus selection without an expected error"
                )
                XCTAssertEqual(
                    selected,
                    scenario.expected.selectedIndex,
                    "scenario \(scenario.id): earliest-index-wins selection disagrees"
                )
                XCTAssertEqual(
                    winningError,
                    expectedError,
                    "scenario \(scenario.id): winning error disagrees"
                )
                XCTAssertEqual(
                    palette[selected].hex,
                    scenario.expected.selectedHexColor,
                    "scenario \(scenario.id): selected hex color disagrees"
                )

                let tied = results.enumerated().compactMap { pair -> Int? in
                    guard case .value(let value) = pair.element, value == winningError else { return nil }
                    return pair.offset
                }
                XCTAssertEqual(
                    tied,
                    scenario.expected.tiedIndices,
                    "scenario \(scenario.id): tie evidence disagrees"
                )
                XCTAssertEqual(
                    scenario.expected.tieBroke,
                    tied.count > 1,
                    "scenario \(scenario.id): tie_broke disagrees"
                )
                XCTAssertEqual(
                    tied.first,
                    selected,
                    "scenario \(scenario.id): selected index must lead the tied set"
                )
            }
        }
    }

    // MARK: - Solver selection parity

    /// Replays every solver-representable scenario through
    /// `CompositionSolver` on a 1×1 grid, pinning the production fast path
    /// (and its earliest-wins tie-breaking) to the corpus selections.
    ///
    /// Scenarios whose target is itself missing a positively-weighted channel
    /// (a target the solver cannot construct, since its targets come from
    /// fully-materialized source grids) are covered by the scorer test above.
    func testSolverSelectionMatchesEveryReplayableScenario() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let palette = try orderedPalette(scenario)
            let weights = channelWeights(scenario.weights)
            let targetChannels = scenario.target.channels

            let replayable = weights.activeEntries.allSatisfy { targetChannels[$0.condition.rawValue] != nil }
            if !replayable { continue }

            var sourceGrids: [LightingCondition: BrightnessGrid] = [:]
            for (key, value) in targetChannels {
                if let condition = LightingCondition(rawValue: key) {
                    sourceGrids[condition] = BrightnessGrid(width: 1, height: 1, values: [value])
                }
            }

            let result = try CompositionSolver().solve(
                palette: palette,
                sourceGrids: sourceGrids,
                weights: weights
            )

            if let selected = scenario.expected.selectedIndex {
                let expectedError = try XCTUnwrap(
                    scenario.expected.error,
                    "scenario \(scenario.id): corpus selection without an expected error"
                )
                XCTAssertEqual(
                    result.colorIndex(x: 0, y: 0),
                    selected,
                    "scenario \(scenario.id): solver selection disagrees with the corpus"
                )
                XCTAssertEqual(
                    result.error(x: 0, y: 0),
                    expectedError,
                    "scenario \(scenario.id): solver error disagrees with the corpus"
                )
            } else {
                XCTAssertNil(
                    result.colorIndex(x: 0, y: 0),
                    "scenario \(scenario.id): expected the solver to leave the cell unmatched"
                )
                XCTAssertEqual(result.error(x: 0, y: 0), Double.infinity, "scenario \(scenario.id)")
                XCTAssertEqual(
                    result.excludedCandidateCount,
                    palette.count,
                    "scenario \(scenario.id): every candidate should be excluded"
                )
            }
        }
    }
}
